    "Textbox": "Pole tekstowe",
    "The authorised snapshot contains assignment, date, status and score metadata only. Individual answers, signatures and attachments have not been inferred or generated.": "Autoryzowana migawka zawiera wyłącznie metadane przypisania, daty, statusu i wyniku. Indywidualne odpowiedzi, podpisy i załączniki nie zostały wywnioskowane ani wygenerowane.",
    "The authorised snapshot contains this RAMS metadata, but no corresponding PDF or image exists in the local archive. No replacement document has been generated.": "Autoryzowana migawka zawiera metadane RAMS, ale w lokalnym archiwum nie istnieje żaden odpowiadający jej plik PDF ani obraz. Nie wygenerowano żadnego dokumentu zastępczego.",
    "The corresponding imported form definition will appear here.": "Tutaj pojawi się odpowiednia zaimportowana definicja formularza.",
    "The image binaries were not included in the authorised induction snapshot.": "Pliki binarne obrazu nie zostały uwzględnione w autoryzowanej migawce indukcyjnej.",
    "The password is stored only as a PBKDF2 hash.": "Hasło jest przechowywane wyłącznie w postaci skrótu PBKDF2.",
    "The snapshot does not contain per-worker answers, certificate expiry dates, or evidence files for this question. These have not been inferred.": "Migawka nie zawiera odpowiedzi poszczególnych pracowników, dat wygaśnięcia certyfikatów ani plików dowodowych dla tego pytania. Nie zostały one wywnioskowane.",
    "These are exact site-name matches only. The snapshot does not identify which specific induction each worker completed, so no completion has been inferred.": "Są to wyłącznie dokładne dopasowania nazw witryn. Migawka nie określa, które konkretne wdrożenie ukończył każdy pracownik, dlatego nie wywnioskowano żadnego zakończenia.",
