    "The authorised snapshot contains assignment, date, status and score metadata only. Individual answers, signatures and attachments have not been inferred or generated.": "Instantaneul autorizat conține doar metadate privind atribuirea, data, starea și scorul. Răspunsurile individuale, semnăturile și atașamentele nu au fost deduse sau generate.",
    "The authorised snapshot contains this RAMS metadata, but no corresponding PDF or image exists in the local archive. No replacement document has been generated.": "Instantaneul autorizat conține aceste metadate RAMS, dar nu există niciun PDF sau imagine corespunzătoare în arhiva locală. Nu a fost generat niciun document de înlocuire.",
    "The corresponding imported form definition will appear here.": "Definiția corespunzătoare a formularului importat va apărea aici.",
    "The image binaries were not included in the authorised induction snapshot.": "Binarele de imagine nu au fost incluse în instantaneul de inducție autorizat.",
    "The password is stored only as a PBKDF2 hash.": "Parola este stocată doar ca hash PBKDF2.",
    "The snapshot does not contain per-worker answers, certificate expiry dates, or evidence files for this question. These have not been inferred.": "Instantaneul nu conține răspunsuri pentru fiecare lucrător, date de expirare a certificatelor sau fișiere de dovezi pentru această întrebare. Acestea nu au fost deduse.",
    "These are exact site-name matches only. The snapshot does not identify which specific induction each worker completed, so no completion has been inferred.": "Acestea sunt doar potriviri exacte ale numelui site-ului. Instantaneul nu identifică ce inducție specifică a finalizat fiecare lucrător, așa că nu a fost dedusă nicio finalizare.",
    "This browser cannot scan QR codes directly. Paste the worker QR link instead.": "Acest browser nu poate scana direct codurile QR. Lipiți linkul QR al lucrătorului.",
    "This centre contains release decisions and delivery diagnostics.": "Acest centru conține decizii de eliberare și diagnostice de livrare.",
    "This creates the first local application account. Imported customer records will remain read-only.": "Aceasta creează primul cont de aplicație locală. Înregistrările importate ale clienților vor rămâne doar pentru citire.",
    "This is an existing migrated document. The source file and record remain unchanged.": "Acesta este un document migrat existent. Fișierul sursă și înregistrarea rămân neschimbate.",
    "This is the original QR image preserved in the authorised source archive.": "Aceasta este imaginea QR originală păstrată în arhiva sursă autorizată.",
    "This one-time link expires after 30 minutes and signs out every existing session.": "Acest link unic expiră după 30 de minute și se deconectează la fiecare sesiune existentă.",
    "This preview shows the imported form structure and linked assignment metadata. It does not create assignments or submit responses.": "Această previzualizare arată structura formularului importat și metadatele legate de atribuire. Nu creează teme și nu trimite răspunsuri.",
    "This profile shows only fields present in the authorised local snapshot. No details have been inferred or generated.": "Acest profil afișează numai câmpurile prezente în instantaneul local autorizat. Nu au fost deduse sau generate detalii.",
