    "The authorised snapshot contains assignment, date, status and score metadata only. Individual answers, signatures and attachments have not been inferred or generated.": "O snapshot autorizado contém apenas metadados de atribuição, data, status e pontuação. Respostas individuais, assinaturas e anexos não foram inferidos ou gerados.",
    "The authorised snapshot contains this RAMS metadata, but no corresponding PDF or image exists in the local archive. No replacement document has been generated.": "O instantâneo autorizado contém esses metadados RAMS, mas não existe nenhum PDF ou imagem correspondente no arquivo local. Nenhum documento de substituição foi gerado.",
    "The corresponding imported form definition will appear here.": "A definição de formulário importado correspondente aparecerá aqui.",
    "The image binaries were not included in the authorised induction snapshot.": "Os binários de imagem não foram incluídos no instantâneo de indução autorizado.",
    "The password is stored only as a PBKDF2 hash.": "A senha é armazenada apenas como um hash PBKDF2.",
    "The snapshot does not contain per-worker answers, certificate expiry dates, or evidence files for this question. These have not been inferred.": "O instantâneo não contém respostas por trabalhador, datas de expiração de certificados ou arquivos de evidências para esta pergunta. Estes não foram inferidos.",
    "These are exact site-name matches only. The snapshot does not identify which specific induction each worker completed, so no completion has been inferred.": "Estas são apenas correspondências exatas de nomes de sites. O instantâneo não identifica qual indução específica cada trabalhador concluiu, portanto, nenhuma conclusão foi inferida.",
    "This browser cannot scan QR codes directly. Paste the worker QR link instead.": "Este navegador não pode ler códigos QR diretamente. Cole o link QR do trabalhador.",
    "This centre contains release decisions and delivery diagnostics.": "Este centro contém decisões de liberação e diagnósticos de entrega.",
    "This creates the first local application account. Imported customer records will remain read-only.": "Isso cria a primeira conta de aplicativo local. Os registros de clientes importados permanecerão somente leitura.",
    "This is an existing migrated document. The source file and record remain unchanged.": "Este é um documento migrado existente. O arquivo de origem e o registro permanecem inalterados.",
