    "This one-time link expires after 30 minutes and signs out every existing session.": "Este link único expira após 30 minutos e desconecta todas as sessões existentes.",
    "This preview shows the imported form structure and linked assignment metadata. It does not create assignments or submit responses.": "Esta visualização mostra a estrutura do formulário importado e os metadados da tarefa vinculados. Ele não cria tarefas nem envia respostas.",
