    "Textbox": "Текстове поле",
    "The authorised snapshot contains assignment, date, status and score metadata only. Individual answers, signatures and attachments have not been inferred or generated.": "Авторизований знімок містить лише метадані про призначення, дату, статус і оцінку. Індивідуальні відповіді, підписи та вкладення не були виведені та згенеровані.",
    "The authorised snapshot contains this RAMS metadata, but no corresponding PDF or image exists in the local archive. No replacement document has been generated.": "Авторизований знімок містить ці метадані RAMS, але в локальному архіві немає відповідного PDF-файлу чи зображення. Документ на заміну не створено.",
    "The corresponding imported form definition will appear here.": "Тут з’явиться відповідне імпортоване визначення форми.",
    "The image binaries were not included in the authorised induction snapshot.": "Подвійні файли зображення не були включені в авторизований індукційний знімок.",
    "The password is stored only as a PBKDF2 hash.": "Пароль зберігається лише як хеш PBKDF2.",
    "The snapshot does not contain per-worker answers, certificate expiry dates, or evidence files for this question. These have not been inferred.": "Знімок не містить відповідей для кожного працівника, термінів дії сертифікатів або файлів доказів для цього запитання. Ці висновки не зроблено.",
    "These are exact site-name matches only. The snapshot does not identify which specific induction each worker completed, so no completion has been inferred.": "Це лише точні збіги назв сайтів. Знімок не визначає, яку конкретну індукцію завершив кожен працівник, тому завершення не було зроблено.",
    "This browser cannot scan QR codes directly. Paste the worker QR link instead.": "Цей браузер не може безпосередньо сканувати QR-коди. Натомість вставте робоче QR-посилання.",
    "This centre contains release decisions and delivery diagnostics.": "Цей центр містить рішення щодо випуску та діагностику доставки.",
    "This creates the first local application account. Imported customer records will remain read-only.": "Це створює перший обліковий запис локальної програми. Імпортовані записи клієнтів залишаться доступними лише для читання.",
    "This is an existing migrated document. The source file and record remain unchanged.": "Це наявний перенесений документ. Вихідний файл і запис залишаються незмінними.",
    "This is the original QR image preserved in the authorised source archive.": "Це оригінальне QR-зображення, яке зберігається в авторизованому архіві джерела.",
    "This one-time link expires after 30 minutes and signs out every existing session.": "Термін дії цього одноразового посилання закінчується через 30 хвилин і призводить до завершення кожного наявного сеансу.",
    "This preview shows the imported form structure and linked assignment metadata. It does not create assignments or submit responses.": "Цей попередній перегляд показує імпортовану структуру форми та пов’язані метадані призначення. Він не створює завдань і не надсилає відповіді.",
    "This profile shows only fields present in the authorised local snapshot. No details have been inferred or generated.": "Цей профіль показує лише поля, наявні в авторизованому локальному знімку. Жодних подробиць не було зроблено чи згенеровано.",
    "This state comes directly from the imported customer snapshot.": "Цей стан походить безпосередньо з імпортованого знімка клієнта.",
    "This value is stored on the training-question record and is not a worker certificate expiry date.": "Це значення зберігається в записі навчальних запитань і не є датою закінчення терміну дії сертифіката працівника.",
