    "Textbox": "Текстовое поле",
    "The authorised snapshot contains assignment, date, status and score metadata only. Individual answers, signatures and attachments have not been inferred or generated.": "Авторизованный снимок содержит только метаданные назначения, даты, статуса и оценок. Отдельные ответы, подписи и вложения не были выведены или созданы.",
    "The authorised snapshot contains this RAMS metadata, but no corresponding PDF or image exists in the local archive. No replacement document has been generated.": "Авторизованный снимок содержит эти метаданные RAMS, но в локальном архиве не существует соответствующего PDF-файла или изображения. Документ на замену не создан.",
    "The corresponding imported form definition will appear here.": "Здесь появится соответствующее определение импортированной формы.",
    "The image binaries were not included in the authorised induction snapshot.": "Двоичные файлы изображений не были включены в авторизованный вводный снимок.",
    "The password is stored only as a PBKDF2 hash.": "Пароль хранится только в виде хеша PBKDF2.",
    "The snapshot does not contain per-worker answers, certificate expiry dates, or evidence files for this question. These have not been inferred.": "Снимок не содержит ответов каждого работника, дат истечения срока действия сертификата или файлов доказательств по этому вопросу. Эти выводы не были сделаны.",
    "These are exact site-name matches only. The snapshot does not identify which specific induction each worker completed, so no completion has been inferred.": "Это только точные совпадения названий сайтов. На снимке не указано, какой конкретный вводный курс завершил каждый работник, поэтому вывод о завершении не сделан.",
    "This browser cannot scan QR codes directly. Paste the worker QR link instead.": "Этот браузер не может сканировать QR-коды напрямую. Вместо этого вставьте QR-ссылку работника.",
    "This centre contains release decisions and delivery diagnostics.": "Этот центр содержит решения о выпуске и диагностику доставки.",
    "This creates the first local application account. Imported customer records will remain read-only.": "При этом создается первая учетная запись локального приложения. Импортированные записи клиентов останутся доступными только для чтения.",
    "This is an existing migrated document. The source file and record remain unchanged.": "Это существующий перенесенный документ. Исходный файл и запись остаются неизменными.",
    "This is the original QR image preserved in the authorised source archive.": "Это оригинальное QR-изображение, сохраненное в авторизованном исходном архиве.",
    "This one-time link expires after 30 minutes and signs out every existing session.": "Срок действия этой одноразовой ссылки истекает через 30 минут и приводит к выходу из каждого существующего сеанса.",
    "This preview shows the imported form structure and linked assignment metadata. It does not create assignments or submit responses.": "В предварительном просмотре показана структура импортированной формы и связанные метаданные задания. Он не создает задания и не отправляет ответы.",
    "This profile shows only fields present in the authorised local snapshot. No details have been inferred or generated.": "В этом профиле отображаются только поля, присутствующие в авторизованном локальном снимке. Никаких подробностей не было выведено или сгенерировано.",
    "This state comes directly from the imported customer snapshot.": "Это состояние берется непосредственно из импортированного снимка клиента.",
    "This value is stored on the training-question record and is not a worker certificate expiry date.": "Это значение сохраняется в записи обучающего вопроса и не является датой истечения срока действия сертификата работника.",
