    "Textbox": "Cuadro de texto",
    "The authorised snapshot contains assignment, date, status and score metadata only. Individual answers, signatures and attachments have not been inferred or generated.": "La instantánea autorizada contiene metadatos de asignación, fecha, estado y puntuación únicamente. No se han inferido ni generado respuestas individuales, firmas y archivos adjuntos.",
    "The authorised snapshot contains this RAMS metadata, but no corresponding PDF or image exists in the local archive. No replacement document has been generated.": "La instantánea autorizada contiene estos metadatos RAMS, pero no existe ningún PDF o imagen correspondiente en el archivo local. No se ha generado ningún documento de reemplazo.",
    "The corresponding imported form definition will appear here.": "La definición de formulario importada correspondiente aparecerá aquí.",
    "The image binaries were not included in the authorised induction snapshot.": "Los binarios de imágenes no se incluyeron en la instantánea de inducción autorizada.",
    "The password is stored only as a PBKDF2 hash.": "La contraseña se almacena únicamente como un hash PBKDF2.",
    "The snapshot does not contain per-worker answers, certificate expiry dates, or evidence files for this question. These have not been inferred.": "La instantánea no contiene respuestas por trabajador, fechas de vencimiento de certificados ni archivos de evidencia para esta pregunta. Estos no han sido inferidos.",
    "These are exact site-name matches only. The snapshot does not identify which specific induction each worker completed, so no completion has been inferred.": "Estas son coincidencias exactas de nombres de sitios únicamente. La instantánea no identifica qué inducción específica completó cada trabajador, por lo que no se ha inferido ninguna finalización.",
    "This browser cannot scan QR codes directly. Paste the worker QR link instead.": "Este navegador no puede escanear códigos QR directamente. En su lugar, pegue el enlace QR del trabajador.",
    "This centre contains release decisions and delivery diagnostics.": "Este centro contiene decisiones de liberación y diagnósticos de entrega.",
    "This creates the first local application account. Imported customer records will remain read-only.": "Esto crea la primera cuenta de aplicación local. Los registros de clientes importados seguirán siendo de solo lectura.",
    "This is an existing migrated document. The source file and record remain unchanged.": "Este es un documento migrado existente. El archivo fuente y el registro permanecen sin cambios.",
    "This is the original QR image preserved in the authorised source archive.": "Esta es la imagen QR original conservada en el archivo fuente autorizado.",
    "This one-time link expires after 30 minutes and signs out every existing session.": "Este enlace único caduca después de 30 minutos y cierra sesión en todas las sesiones existentes.",
    "This preview shows the imported form structure and linked assignment metadata. It does not create assignments or submit responses.": "Esta vista previa muestra la estructura del formulario importado y los metadatos de la tarea vinculados. No crea tareas ni envía respuestas.",
    "This profile shows only fields present in the authorised local snapshot. No details have been inferred or generated.": "Este perfil muestra solo los campos presentes en la instantánea local autorizada. No se han inferido ni generado detalles.",
    "This state comes directly from the imported customer snapshot.": "Este estado proviene directamente de la instantánea del cliente importada.",
